const worship17={
 read:['Oxundu','Okundu','Прочитано','Read','مقروء'],markRead:['Oxundu kimi işarələ','Okundu işaretle','Отметить прочитанной','Mark as read','تحديد كمقروء'],bookmark:['Burada qaldım','Burada kaldım','Остановился здесь','Save my place','حفظ موضعي'],resume:['Qaldığım yerdən davam et','Kaldığım yerden devam et','Продолжить чтение','Resume reading','متابعة القراءة'],verse:['Ayə','Ayet','Аят','Verse','آية'],clear:['İşarəni sil','İşareti kaldır','Удалить закладку','Remove bookmark','إزالة العلامة'],maps:['Xəritədə aç','Haritada aç','Открыть на карте','Open in maps','افتح في الخرائط'],distance:['Seçilmiş ərazinin mərkəzindən düz xətt məsafəsi','Seçili alanın merkezinden kuş uçuşu mesafe','Расстояние по прямой от центра выбранной области','Straight-line distance from the selected area centre','المسافة المباشرة من مركز المنطقة المختارة'],
 qada:['Qalıq qəza','Kalan kaza','Осталось восполнить','Remaining make-up fasts','صيام القضاء المتبقي'],madeUp:['Qəzasını tutdum','Kazasını tuttum','Восполнено','Made up','تم القضاء'],qadaNote:['Qəza qeydi şəxsi izləmə üçündür. Yalnız qeyd etdiyiniz buraxılmış Ramazan günləri hesablanır; bu, dini hökm deyil.','Kaza kaydı kişisel takiptir. Yalnız kaydettiğiniz tutulmamış Ramazan günleri sayılır; dini hüküm değildir.','Это личный учёт пропущенных дней Рамадана, а не религиозное постановление.','A personal tracker of recorded missed Ramadan days, not a religious ruling.','سجل شخصي لأيام رمضان الفائتة المسجلة، وليس حكمًا شرعيًا.'],qadaList:['Qəza qeydlərim','Kaza kayıtlarım','Пропущенные дни','My make-up records','سجل القضاء'],
 qadr:['Qədr gecələri','Kadir geceleri','Ночи предопределения','Nights of Qadr','ليالي القدر'],qadrActs:['Qədr gecəsi əməlləri','Kadir gecesi ibadetleri','Поклонение в ночь Кадр','Worship on Qadr nights','أعمال ليلة القدر'],evening:['Axşam başlayır','Akşam başlar','Начало вечером','Begins in the evening','تبدأ مساءً'],night:['Ramazan gecəsi','Ramazan gecesi','Ночь Рамадана','Night of Ramadan','ليلة رمضان'],calendarNote:['Tarixlər Ümmül-Qura təqviminə əsaslanır; yerli hilal müşahidəsinə görə fərqlənə bilər. Gecə əvvəlki mülki günün günbatımında başlayır.','Tarihler Ümmülkura takvimine göre; yerel hilal gözlemine göre değişebilir. Gece önceki sivil günün günbatımında başlar.','Даты по Умм аль-Кура могут отличаться по местному наблюдению луны. Ночь начинается на закате предыдущей календарной даты.','Dates use Umm al-Qura and may differ with local moon sightings. Each night begins at sunset on the preceding civil date.','التواريخ وفق أم القرى وقد تختلف بالرؤية المحلية. تبدأ الليلة بغروب اليوم المدني السابق.'],
 hanafiNote:['Hənəfi/Sünni ənənəsində son on günün tək gecələri: 21, 23, 25, 27, 29. Ən çox 27-ci gecə qeyd olunur; dəqiq gecə qəti bilinmir.','Hanefi/Sünni gelenekte son on günün tek geceleri: 21, 23, 25, 27, 29. En çok 27. gece anılır; kesin gece bilinmez.','В ханафитской/суннитской традиции: нечётные ночи 21, 23, 25, 27, 29; часто отмечают 27-ю. Точная ночь неизвестна.','Hanafi/Sunni practice seeks the odd nights 21, 23, 25, 27 and 29, commonly observing the 27th; the exact night is not certain.','في التقليد السني الحنفي تُتحرى ليالي ٢١ و٢٣ و٢٥ و٢٧ و٢٩، وتُحيى غالبًا ليلة ٢٧ دون الجزم بها.'],jafariNote:['Cəfəri/Şiə ənənəsində 19, 21 və 23-cü gecələr xüsusilə əhya edilir.','Caferi/Şii gelenekte 19, 21 ve 23. geceler özellikle ihya edilir.','В джафаритской/шиитской традиции особо отмечают ночи 19, 21 и 23.','Jafari/Shia observance particularly honours the 19th, 21st and 23rd nights.','في التقليد الشيعي الجعفري تُحيى خصوصًا ليالي ١٩ و٢١ و٢٣.'],
 acts:['Quran oxu və mənası üzərində düşün. Dua və istiğfar et, ehtiyacı olana yardım göstər. Gecəni imkanın daxilində ibadətlə keçir.','Kur’an oku ve anlamını düşün. Dua ve istiğfar et, ihtiyaç sahibine yardım et. İmkânın ölçüsünde geceyi ibadetle geçir.','Читайте Коран и размышляйте о смысле, молитесь, просите прощения и помогайте нуждающимся по силам.','Read and reflect on the Quran, supplicate, seek forgiveness and help those in need as you are able.','اقرأ القرآن وتدبره، وادع واستغفر وساعد المحتاجين بحسب استطاعتك.'],jafariActs:['Qədr gecələrində qüsl müstəhəbdir. Müstəhəb namazları fərdi qıl; təfərrüatlar üçün təqlid etdiyin mərcənin göstərişinə bax.','Kadir gecelerinde gusül müstehaptır. Nafileleri bireysel kıl; ayrıntılar için merciinin rehberine bak.','Гусль в ночи Кадр желателен. Добровольные молитвы совершайте индивидуально; детали уточняйте у своего марджа.','Ghusl on Qadr nights is recommended. Offer voluntary prayers individually; consult your marja for details.','يستحب غسل ليالي القدر. صل النوافل فرادى وراجع مرجعك للتفاصيل.'],duaMeaning:['Allahım, Sən əfv edənsən, əfv etməyi sevirsən, məni əfv et.','Allah’ım, Sen affedicisin, affetmeyi seversin; beni affet.','Аллах, Ты Прощающий, любишь прощать — прости меня.','O Allah, You pardon and love to pardon; pardon me.','اللهم إنك عفو تحب العفو فاعف عني.']};
function w17(k){return worship17[k]?.[['az','tr','ru','en','ar'].indexOf(lang())]||worship17[k]?.[0]||k}
function quranProgress(){const s=read('shams-quran-progress',{});return {read:s.read&&typeof s.read==='object'?s.read:{},bookmarks:s.bookmarks&&typeof s.bookmarks==='object'?s.bookmarks:{}}}
function toggleSurahRead(id){if(!surahs.some(s=>s.number===id))return;const s=quranProgress();s.read[id]=!s.read[id];save('shams-quran-progress',s);render()}
function bookmarkVerse(id,verse){const s=quranProgress();s.bookmarks[id]=verse;save('shams-quran-progress',s);const existing=document.querySelector('.reading-resume');if(existing)existing.outerHTML=quranResumeHTML(id);else document.querySelector('.reading')?.insertAdjacentHTML?.('afterbegin',quranResumeHTML(id));document.querySelectorAll('[data-bookmark]').forEach(b=>{const chosen=Number(b.dataset.bookmark)===verse;b.setAttribute('aria-pressed',chosen);b.classList.toggle('saved',chosen)});toast(w17('bookmark')+' · '+w17('verse')+' '+verse)}
function clearQuranBookmark(id){const s=quranProgress();delete s.bookmarks[id];save('shams-quran-progress',s);render()}
function jumpQuranBookmark(id){const n=quranProgress().bookmarks[id];const e=document.querySelector('#verse-'+n);e?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});e?.focus({preventScroll:true})}
function quranResumeHTML(id){const verse=quranProgress().bookmarks[id];return verse?`<div class="reading-resume" data-localized="true"><button class="secondarybtn" onclick="jumpQuranBookmark(${id})">${w17('resume')} · ${w17('verse')} ${Number(verse)}</button><button class="textbtn" onclick="clearQuranBookmark(${id})" aria-label="${w17('clear')}">×</button></div>`:''}
function openMosqueMaps(i){const m=mosqueState.items[i];if(!m)return;const ll=m.lat+','+m.lon;showContentModal(modalHeading(w17('maps'))+`<h3>${esc(m.name)}</h3><p>${mosqueDistance(m,mosqueState.origin||mosqueState).toFixed(1)} km</p><div class="map-choices">${[['Waze','https://www.waze.com/ul?ll='+ll+'&navigate=yes'],['Google Maps','https://www.google.com/maps/dir/?api=1&destination='+ll],['Apple Maps','https://maps.apple.com/?daddr='+ll+'&dirflg=d']].map(([name,url])=>`<a class="secondarybtn" href="${url}" target="_blank" rel="noopener">${name}</a>`).join('')}</div>`)}
function qadaRecords(){const raw=read('shams-qada',{});return raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:{}}
function isRamadanDate(k){try{return hijriParts(dateFromKey(k)).month===9}catch{return false}}
function remainingQada(j=fastingJournal()){const made=qadaRecords();return Object.keys(j).filter(k=>j[k].status==='missed'&&isRamadanDate(k)&&!made[k]).length}
function toggleQada(k){const j=fastingJournal();if(j[k]?.status!=='missed'||!isRamadanDate(k))return;const q=qadaRecords();q[k]=!q[k];save('shams-qada',q);render()}
function qadaHTML(){const j=fastingJournal(),q=qadaRecords(),rows=Object.keys(j).filter(k=>j[k].status==='missed'&&isRamadanDate(k)).sort().reverse();return `<details class="card" data-localized="true"><summary>${w17('qadaList')} · ${remainingQada(j)}</summary><p class="notice">${w17('qadaNote')}</p>${rows.map(k=>`<label class="qada-row"><span>${localizedDate(dateFromKey(k))}<small>${ux(j[k].reason)}</small></span><span><input type="checkbox" ${q[k]?'checked':''} onchange="toggleQada('${k}')">${w17('madeUp')}</span></label>`).join('')||`<p>${cw('empty')}</p>`}</details>`}
let qadrSchool='hanafi';
function qadrNights(){return qadrSchool==='jafari'?[19,21,23]:[21,23,25,27,29]}
function qadrDateClass(h){return h.month===9&&qadrNights().includes(h.day+1)?'qadr-date':''}
function qadrHTML(){const season=ramadanSeason(ramadanYear||upcomingRamadanYear()),j=qadrSchool==='jafari';return `<section class="card qadr-panel" data-localized="true"><h2>${w17('qadr')}</h2><div class="tabs"><button class="${!j?'active':''}" onclick="qadrSchool='hanafi';render()">${tr('Hənəfi')}</button><button class="${j?'active':''}" onclick="qadrSchool='jafari';render()">${tr('Cəfəri')}</button></div><label>${rm('season')}<select aria-label="${rm('season')}" onchange="setRamadanYear(this.value)">${Array.from({length:5},(_,i)=>season.year-2+i).map(y=>`<option ${season.year===y?'selected':''}>${y}</option>`).join('')}</select></label><p>${w17(j?'jafariNote':'hanafiNote')}</p>${qadrNights().map(n=>{const morning=season.dates[n-1],d=dateFromKey(morning);d.setDate(d.getDate()-1);return `<button class="qadr-date-row" onclick="journalMonth=dateFromKey('${key(d)}');render()"><b>${n} · ${w17('night')}</b><span>${w17('evening')}: ${localizedDate(d)}</span></button>`}).join('')}<p class="notice">${w17('calendarNote')}</p><details><summary>${w17('qadrActs')}</summary><p>${w17('acts')}</p>${j?`<p>${w17('jafariActs')}</p><a class="source-link" href="https://www.sistani.org/english/book/26890/8487/" target="_blank" rel="noopener">Sistani · ${ml('source')}</a>`:`<p class="arabic" lang="ar" dir="rtl">اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي</p><p>${w17('duaMeaning')}</p><a class="source-link" href="https://sunnah.com/tirmidhi:3513" target="_blank" rel="noopener">Tirmidhi 3513</a>`}<p><a class="source-link" href="${j?'https://www.al-khoei.org/events-in-ramadan/':'https://www.diyanet.gov.tr/icerik/10144'}" target="_blank" rel="noopener">${j?'Al-Khoei Foundation':'Diyanet'} · ${ml('source')}</a></p></details></section>`}
function initializeRelease17(){
 cloudBackupKeys.push('shams-quran-progress','shams-qada');
 for(const [k,v]of Object.entries(worship17))uiMap.set(v[0],v);
 const ramadan=cosmicRamadan;cosmicRamadan=function(){return ramadan()+qadaHTML()+qadrHTML()};
 initializeCommunity();
}
